"""Build accessible film/transcript/storyboard and numerical explorer pages."""
from pathlib import Path
import json,html,importlib.util
HERE=Path(__file__).resolve().parent;ROOT=HERE.parent
# Use common page shell without rerunning source-copy/build operations.
text=(HERE/'build_site.py').read_text();start=text.index('NAV=');end=text.index("source='https:")
ns={'ROOT':ROOT};exec(text[start:end],ns)
page=ns['page'];hero=ns['hero'];section=ns['section'];card=ns['card']
STORY=json.loads((HERE/'STORYBOARD.json').read_text())
body=hero('Four films / ACR1','Watch the system. Inspect the source.','Short editorial films combine accepted CAD-derived views, explicitly conceptual motion diagrams and frozen numerical results. All information is also available as text and stills.')
body+=section('Complete journey','From cassette to orbit.','<p>A 190-second film follows the actual CAD-derived storage, feed, handoff, launch and recovery sequence, then a host-assisted orbit illustration and matched spring-deployer comparison.</p><a class="button" href="delivery-film.html">Watch the complete film →</a>')
body+=section('Choose a route','Four focused explanations.','<div class="grid four">'+''.join(card(data['title'],data['scope']+f' · {data["duration_s"]} s',f'#{key}','Open film')for key,data in STORY.items())+'</div>')
for key,data in STORY.items():
 body+=section(data['scope'],data['title'],f'''<div class="film" id="{key}"><div class="still-alternative"><img src="films/{key}/poster.jpg" alt="Poster: {data['title']}" width="1280" height="720"><div class="finding"><p>Reduced motion is enabled. Read the <a href="film-{key}-transcript.html">transcript</a> or <a href="film-{key}-storyboard.html">still storyboard</a>, or choose playback.</p><button class="motion-override" type="button">Show video controls</button></div></div><video controls muted playsinline preload="none" poster="films/{key}/poster.jpg" aria-label="{data['title']}"><source src="films/{key}/film.webm" type="video/webm"><source src="films/{key}/film.mp4" type="video/mp4"><track kind="captions" src="films/{key}/captions.vtt" srclang="en" label="English" default><p>Read the <a href="film-{key}-transcript.html">full transcript</a> or download the film.</p></video><div class="film-notes"><p>{data['duration_s']} seconds · explicit playback · silent editorial film with English captions</p><div class="film-links"><a href="film-{key}-transcript.html">Read transcript</a><a href="film-{key}-storyboard.html">Still storyboard</a><a href="films/{key}/film.mp4" download>Download MP4</a><a href="films/{key}/film.webm" download>Download WebM</a><a href="films/{key}/captions.vtt" download>Captions (VTT)</a><a href="films/{key}/FILM_MANIFEST.json">Source & provenance</a></div></div></div>''')
 transcript=json.loads((ROOT/f'films/{key}/transcript.json').read_text())
 transcript_body=hero(data['scope']+' / transcript',data['title'],'Complete text and source references for the silent film. Each timed segment includes its evidence class.')
 transcript_body+='<div class="wrap"><a class="text-link" href="films.html#'+key+'">Return to film →</a><ol class="transcript">'
 for x in transcript:
  transcript_body+=f'<li><time>{x["start_s"]}–{x["end_s"]} s</time><h3>{html.escape(x["title"])}</h3><p>{html.escape(x["text"])}</p><p class="source-note">{html.escape(x["evidence_class"])}<br>Source: {html.escape(x["source"])}</p></li>'
 transcript_body+='</ol></div>'
 page(f'film-{key}-transcript.html',data['title']+' · transcript',transcript_body)
 storyboard_body=hero(data['scope']+' / stills',data['title'],'A complete still alternative to video. The original full-resolution scientific figures and CAD view provenance remain available in the asset register.')
 storyboard_body+='<div class="wrap"><p><a href="films.html#'+key+'">Return to film</a> · <a href="film-'+key+'-transcript.html">Read complete transcript</a></p><div class="storyboard">'
 for i,x in enumerate(transcript):
  storyboard_body+=f'<figure><a href="films/{key}/storyboard-{i+1:02d}.png"><img src="films/{key}/storyboard-{i+1:02d}.jpg" alt="{html.escape(x["title"])} {html.escape(x["text"])}" width="1280" height="720" loading="lazy"></a><figcaption><b>{x["start_s"]}–{x["end_s"]} s · {html.escape(x["title"])}</b><p>{html.escape(x["text"])}</p>{html.escape(x["evidence_class"])}</figcaption></figure>'
 storyboard_body+='</div></div>'
 page(f'film-{key}-storyboard.html',data['title']+' · still storyboard',storyboard_body)
body+=section('Source package','Rebuild the films offline.','''<p>The editable source retains every slide, duration, source identity and diagram coordinate. The original CAD scene remains in the separate Blender source archive. Motion diagrams explain the sequence and are explicitly labelled; they are not CAD kinematic or hardware measurements.</p><div class="actions"><a class="button" href="downloads/VOLLEY_ACR1_film_sources.zip">Download film sources</a><a class="text-link" href="visual-source/STORYBOARD_REVIEW.json">Review receipt</a><a class="text-link" href="visual-source/STORYBOARD.json">Storyboard source</a></div>''')
page('films.html','Four source-driven films',body)
data=json.loads((ROOT/'assets/acr1/trajectory-explorer.json').read_text());points=' '.join(f'{x["px"]},{x["py"]}'for x in data['samples'])
explorer=hero('Numerical explorer / G5-MISSION-01','Follow the computed host history.','Inspect the frozen uniform-2 Gen5 case through its first nominal orbit. This is an inertial X/Z projection of numerical output, with Earth shown to scale. No trajectories are generated in the browser.')
explorer+=section('Source trajectory','Move through simulation time.',f'''<div class="explorer" data-trajectory><label for="time">Recorded sample (first nominal orbit)</label><input id="time" type="range" min="0" max="{len(data['samples'])-1}" step="1" value="0" aria-describedby="trajectory-description"><output for="time" aria-live="polite"></output><svg viewBox="0 0 800 800" role="img" aria-labelledby="trajectory-title trajectory-description"><title id="trajectory-title">Computed host trajectory in the inertial X/Z plane</title><desc id="trajectory-description">Earth is a circle of radius 6378.137 km. The plotted path is from the frozen uniform-2 Gen5 host trajectory. The marker follows the range control. Projection omits the Y coordinate.</desc><circle cx="400" cy="400" r="318.90685" fill="#dbe3e4" stroke="#899a9e"/><polyline points="{points}" fill="none" stroke="#386958" stroke-width="2"/><circle id="host-marker" cx="744" cy="400" r="5" fill="#11161c"/><text x="20" y="35" font-size="18" fill="#11161c">X / Z inertial projection · Earth to scale</text><text x="380" y="780" font-size="17" fill="#11161c">X →</text><text x="15" y="390" font-size="17" fill="#11161c">Z ↑</text></svg></div><script type="application/json" id="trajectory-data">{json.dumps(data)}</script><p>Source: <a href="visual-source/inputs/uniform_2_gen5_f0.35_trajectory.csv">recorded trajectory CSV</a>. The model uses fixed-axis J2 point masses, constant inertial host force and coupled release recoil. This is numerical output, not flight tracking.</p><p><a href="orbital-analysis.html">Read the mission assumptions and comparison</a> · <a href="assets/acr1/TARGETS.json">All twelve frozen target states</a></p>''')
page('orbit-explorer.html','Computed host trajectory',explorer)
print('Built film, transcript, storyboard and source trajectory pages.')
